const CACHE='linkmap-web-v081-dc-room-camera';const FILES=['./','./index.html','./style.css','./app.js','./icons.js','./map-model.js','./map-view.js','./privacy.html','./demo-data.js','./protocol.js','./storage.js','./google.js','./config.js','./assets/nebula.png','./assets/icon.svg','./assets/facebook.svg','./assets/tiktok.svg','./assets/github.svg','./assets/googledrive.svg'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting();});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('linkmap-web-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||!FILES.some(p=>new URL(p,location.href).pathname===u.pathname))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request)));});
